from openpyxl import load_workbook

def print_sheet(sheet, max_row=50, max_col=15):
    print(f"--- Sheet: {sheet.title} ---")
    for i, row in enumerate(sheet.iter_rows(values_only=True)):
        if i >= max_row:
            break
        row_str = "\t".join([str(cell) if cell is not None else "" for cell in row[:max_col]])
        print(f"{i+1}: {row_str}")

try:
    wb = load_workbook('gdp.xlsx', data_only=True)
    if 'Task' in wb.sheetnames:
        print_sheet(wb['Task'], max_row=45)

    if 'Data' in wb.sheetnames:
        print("\n--- Data Sheet ---")
        sheet = wb['Data']
        # Print headers
        for i, row in enumerate(sheet.iter_rows(values_only=True)):
            if i < 5:
                print(f"{i+1}: {row}")
            elif 20 <= i <= 40:
                print(f"{i+1}: {row}")

except Exception as e:
    print(f"Error: {e}")

